package main

import "fmt"

// node is an internal doubly-linked-list node.
type node struct {
	key, value interface{}
	prev, next *node
}

// LRUCache is an O(1) LRU cache backed by a doubly-linked list and a map.
type LRUCache struct {
	capacity int
	m        map[interface{}]*node
	head     *node // sentinel (most-recently-used side)
	tail     *node // sentinel (least-recently-used side)
}

// NewLRUCache creates a cache with the given capacity.
func NewLRUCache(capacity int) *LRUCache {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	head := &node{}
	tail := &node{}
	head.next = tail
	tail.prev = head
	return &LRUCache{
		capacity: capacity,
		m:        make(map[interface{}]*node, capacity),
		head:     head,
		tail:     tail,
	}
}

func (c *LRUCache) remove(n *node) {
	n.prev.next = n.next
	n.next.prev = n.prev
}

func (c *LRUCache) pushFront(n *node) {
	n.next = c.head.next
	n.prev = c.head
	c.head.next.prev = n
	c.head.next = n
}

// Get returns the value for key and marks it as most-recently used.
// The second return value reports whether the key was found.
func (c *LRUCache) Get(key interface{}) (interface{}, bool) {
	n, ok := c.m[key]
	if !ok {
		return nil, false
	}
	c.remove(n)
	c.pushFront(n)
	return n.value, true
}

// Put inserts or updates key. Evicts the least-recently-used entry when full.
func (c *LRUCache) Put(key, value interface{}) {
	if n, ok := c.m[key]; ok {
		n.value = value
		c.remove(n)
		c.pushFront(n)
		return
	}
	n := &node{key: key, value: value}
	c.m[key] = n
	c.pushFront(n)
	if len(c.m) > c.capacity {
		lru := c.tail.prev
		c.remove(lru)
		delete(c.m, lru.key)
	}
}

// Delete removes key and returns its value and whether it existed.
func (c *LRUCache) Delete(key interface{}) (interface{}, bool) {
	n, ok := c.m[key]
	if !ok {
		return nil, false
	}
	c.remove(n)
	delete(c.m, n.key)
	return n.value, true
}

// Len returns the current number of entries.
func (c *LRUCache) Len() int { return len(c.m) }

// String returns a human-readable representation.
func (c *LRUCache) String() string {
	s := "LRUCache["
	first := true
	for n := c.head.next; n != c.tail; n = n.next {
		if !first {
			s += ", "
		}
		s += fmt.Sprintf("%v:%v", n.key, n.value)
		first = false
	}
	return s + fmt.Sprintf("] (cap=%d)", c.capacity)
}

class _Node {
  constructor(key = null, value = null) {
    this.key = key;
    this.value = value;
    this.prev = null;
    this.next = null;
  }
}

/**
 * LRU cache backed by a doubly-linked list and a Map.
 * All operations (get, put, delete) run in O(1) time.
 */
class LRUCache {
  constructor(capacity) {
    if (capacity <= 0) throw new Error("Capacity must be a positive integer.");
    this.capacity = capacity;
    this._map = new Map();
    // Sentinel nodes eliminate edge-case checks.
    this._head = new _Node();
    this._tail = new _Node();
    this._head.next = this._tail;
    this._tail.prev = this._head;
  }

  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  _pushFront(node) {
    node.next = this._head.next;
    node.prev = this._head;
    this._head.next.prev = node;
    this._head.next = node;
  }

  /** Return the value for `key` and mark it as most-recently used. Throws if missing. */
  get(key) {
    const node = this._map.get(key);
    if (!node) throw new Error(`Key not found: ${key}`);
    this._remove(node);
    this._pushFront(node);
    return node.value;
  }

  /** Insert or update `key`. Evicts the LRU entry when full. */
  put(key, value) {
    if (this._map.has(key)) {
      const node = this._map.get(key);
      node.value = value;
      this._remove(node);
      this._pushFront(node);
      return;
    }
    const node = new _Node(key, value);
    this._map.set(key, node);
    this._pushFront(node);
    if (this._map.size > this.capacity) {
      const lru = this._tail.prev;
      this._remove(lru);
      this._map.delete(lru.key);
    }
  }

  /** Remove `key` and return its value. Throws if missing. */
  delete(key) {
    const node = this._map.get(key);
    if (!node) throw new Error(`Key not found: ${key}`);
    this._remove(node);
    this._map.delete(key);
    return node.value;
  }

  get size() {
    return this._map.size;
  }
}

module.exports = { LRUCache };

package main

import "testing"

func TestGetPut(t *testing.T) {
	c := NewLRUCache(2)
	c.Put("a", 1)
	c.Put("b", 2)

	if v, ok := c.Get("a"); !ok || v != 1 {
		t.Fatalf("get a: got %v, %v; want 1, true", v, ok)
	}
	if v, ok := c.Get("b"); !ok || v != 2 {
		t.Fatalf("get b: got %v, %v; want 2, true", v, ok)
	}
}

func TestEviction(t *testing.T) {
	c := NewLRUCache(2)
	c.Put("a", 1)
	c.Put("b", 2)
	c.Put("c", 3) // evicts "a"

	if _, ok := c.Get("a"); ok {
		t.Fatal("expected 'a' to be evicted")
	}
	if v, ok := c.Get("c"); !ok || v != 3 {
		t.Fatalf("get c: got %v, %v; want 3, true", v, ok)
	}
}

func TestUpdateRefreshesRecency(t *testing.T) {
	c := NewLRUCache(2)
	c.Put("a", 1)
	c.Put("b", 2)
	c.Put("a", 10) // refreshes "a"
	c.Put("c", 3)  // should evict "b", not "a"

	if _, ok := c.Get("b"); ok {
		t.Fatal("expected 'b' to be evicted")
	}
	if v, ok := c.Get("a"); !ok || v != 10 {
		t.Fatalf("get a: got %v, %v; want 10, true", v, ok)
	}
}

func TestDelete(t *testing.T) {
	c := NewLRUCache(2)
	c.Put("a", 1)
	c.Put("b", 2)

	v, ok := c.Delete("a")
	if !ok || v != 1 {
		t.Fatalf("delete a: got %v, %v; want 1, true", v, ok)
	}
	if c.Len() != 1 {
		t.Fatalf("len: got %d; want 1", c.Len())
	}
	if _, ok := c.Get("a"); ok {
		t.Fatal("expected 'a' to be gone after delete")
	}

	_, ok = c.Delete("z")
	if ok {
		t.Fatal("expected delete of missing key to return false")
	}
}

func TestGetMissingKey(t *testing.T) {
	c := NewLRUCache(1)
	if _, ok := c.Get("nope"); ok {
		t.Fatal("expected false for missing key")
	}
}

func TestLen(t *testing.T) {
	c := NewLRUCache(3)
	if c.Len() != 0 {
		t.Fatalf("empty cache len: got %d", c.Len())
	}
	c.Put("x", 1)
	c.Put("y", 2)
	if c.Len() != 2 {
		t.Fatalf("len after 2 puts: got %d", c.Len())
	}
	c.Delete("x")
	if c.Len() != 1 {
		t.Fatalf("len after delete: got %d", c.Len())
	}
}

func TestCapacityOne(t *testing.T) {
	c := NewLRUCache(1)
	c.Put("a", 1)
	if v, _ := c.Get("a"); v != 1 {
		t.Fatal("expected a=1")
	}
	c.Put("b", 2) // evicts a
	if _, ok := c.Get("a"); ok {
		t.Fatal("expected a evicted")
	}
	if v, _ := c.Get("b"); v != 2 {
		t.Fatal("expected b=2")
	}
}

